-- 外研社八下 wy8B s5 阅读灌库(junior_reading)· publisher=junior_fltrp · volume=wy8B · grade=8 · 6篇/每篇5题
-- 幂等:按(publisher,volume)先删后插。id/source_key 不预生成。Aaron 跑。
BEGIN;

DELETE FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8B';

-- 6 篇
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U1', 'So much is done for you', 'Every morning, before you wake up, a lot of work is already done for you. The bread on your table is baked during the night. Milk is brought to the shops by trucks while the streets are still empty. The roads are cleaned, and the buses are checked before the day begins.

In a modern city, thousands of jobs are done quietly so that life runs smoothly. Fruit is picked on faraway farms and is sent to markets in your town. Water is made clean before it reaches your home. Even the news you read is written and printed hours before breakfast.

Machines help with much of this work. In some factories, cars are built by robots. In many shops, prices are checked by computers, not by people.

Life is also changing fast. Soon, more work will be done by machines. Some letters will be delivered by small planes. A few cars will be driven without a driver. New energy will be made from the sun and the wind, and less coal will be burned.

Next time you enjoy a quiet morning, think of all the hidden work behind it. So much is done for you, and even more will be done in the years to come.', '城市如何运转(被动·现在/将来)', 207, 2, '[{"q": "When is the bread on your table baked?", "answer": "B", "options": ["In the early morning.", "During the night.", "After breakfast.", "By the buses."], "explanation": "''The bread ... is baked during the night''。"}, {"q": "How are the cars built in some factories?", "answer": "C", "options": ["By drivers.", "By computers.", "By robots.", "By farmers."], "explanation": "''cars are built by robots''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to bake bread at night.", "Why machines are dangerous.", "How much unseen work is done for people in a city.", "Where fruit is grown."], "explanation": "全文讲城市里大量被动完成的隐形工作。"}, {"q": "We can learn from the last part that in the future ____.", "answer": "A", "options": ["even more work will be done by machines", "people will stop using energy", "no bread will be baked", "cities will become quiet"], "explanation": "结尾''even more will be done ... by machines''可推断。"}, {"q": "In the passage, ''hidden work'' means work that is ____.", "answer": "A", "options": ["not easily seen but still done for us", "done only by hand", "never finished", "paid a lot of money"], "explanation": "由全文''隐形完成''可推断 hidden=看不见的。"}]'::jsonb, '[{"word": "baked", "cn": "烘烤(bake的过去分词)"}, {"word": "smoothly", "cn": "顺利地"}, {"word": "robot", "cn": "机器人"}, {"word": "coal", "cn": "煤"}, {"word": "delivered", "cn": "投递(deliver的过去分词)"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U2', 'The library that was saved', 'Years ago, a small library stood at the corner of our street. It was built long ago by the people of the town. Its walls were made of grey stone, and its doors were painted a warm red. As a child, I was often taken there by my grandmother.

One winter, everyone heard sad news: the old library would close. A new shopping centre was planned for that corner, and the little library was no longer needed. Many books were packed into boxes, and the reading room was left cold and empty. The children who had read there were sad, and the old librarian was often seen standing quietly at the locked door.

But the people of the town were not happy. A meeting was held, and hundreds of letters were written to the government. Photos of the library were shared online, and its story was told again and again. Slowly, the whole town was moved by these voices.

In the end, the plan was changed. The library was saved, and money was raised to repair it. The old stone walls were cleaned, and new lights were put in. On the day it opened again, the streets were filled with happy people. Music was played, and fresh flowers were placed on every window.

That library was not just a building. It was loved by everyone, and it was kept alive by the people who cared.', '社区守护(被动·过去)', 235, 2, '[{"q": "What were the walls of the old library made of?", "answer": "B", "options": ["Warm red wood.", "Grey stone.", "Old boxes.", "Bright glass."], "explanation": "''Its walls were made of grey stone''。"}, {"q": "What did the people of the town do to save the library?", "answer": "C", "options": ["They built a shopping centre.", "They packed the books away.", "They held a meeting and wrote many letters.", "They closed the reading room."], "explanation": "''A meeting was held, and hundreds of letters were written''。"}, {"q": "What is the best title''s idea of the passage?", "answer": "C", "options": ["A new shopping centre in town.", "How to build a library.", "People saved their old library because they loved it.", "A cold and empty winter."], "explanation": "全文讲人们出于热爱救回老图书馆。"}, {"q": "From the passage we can infer that the townspeople ____.", "answer": "A", "options": ["cared deeply about their library", "wanted a new shopping centre", "were too busy to help", "never used the library"], "explanation": "写信、开会、分享照片可推断他们很在乎。"}, {"q": "In the passage, ''was moved by these voices'' means the town was ____.", "answer": "A", "options": ["touched and changed by what people said", "carried to a new place", "made quiet and empty", "filled with new buildings"], "explanation": "be moved=被打动;由语境可推断。"}]'::jsonb, '[{"word": "grey", "cn": "灰色的"}, {"word": "government", "cn": "政府"}, {"word": "raised", "cn": "筹集(raise的过去分词)"}, {"word": "repair", "cn": "修理"}, {"word": "packed", "cn": "打包(pack的过去分词)"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U3', 'Reaching the top together', 'Climbing a high mountain is never easy, and no one can do it alone. Last summer, our team of six set out to reach the top of a tall, snowy mountain. Before we started, our leader told us the rules. ''On this mountain, we must stay together,'' he said. ''You must never walk alone, and you have to follow the rope at all times.''

The first days were hard. The air was thin, and we could not walk fast. Some of us felt weak and wanted to give up. But a team can do more than one person can. When someone was tired, another would carry his bag. When the path was steep, we pulled each other up with the rope.

High on the mountain, the weather can change in minutes. One afternoon, dark clouds came, and our leader shouted, ''We have to stop! It might snow tonight. We must build our tents now.'' We could do nothing but wait. All night the cold wind blew. Nobody could sleep well, and our food was almost gone. Still, no one wanted to turn back; giving up was simply not a choice for our team.

The next morning was clear. Step by step, we climbed the last part. At noon, we reached the top at last. From up there, we could see for miles. We had learnt an important lesson: alone you may be strong, but together you can be far stronger.', '团队与登山(情态动词一)', 240, 2, '[{"q": "What rule did the leader give before they started?", "answer": "B", "options": ["They could walk alone if they were fast.", "They must stay together and follow the rope.", "They had to reach the top in one day.", "They should carry no bags."], "explanation": "''we must stay together ... follow the rope''。"}, {"q": "Why did the team have to stop one afternoon?", "answer": "C", "options": ["Because they reached the top.", "Because someone was lost.", "Because dark clouds came and it might snow.", "Because the rope was broken."], "explanation": "''dark clouds came ... It might snow tonight. We must build our tents''。"}, {"q": "What lesson did the team learn?", "answer": "C", "options": ["Mountains are too dangerous to climb.", "One strong person is enough.", "Working together makes people far stronger.", "Summer is the best time to climb."], "explanation": "结尾''together you can be far stronger''。"}, {"q": "We can infer that the writer''s team succeeded mainly because they ____.", "answer": "A", "options": ["helped each other and followed the rules", "climbed as fast as they could", "each walked alone", "had very good weather"], "explanation": "互相帮助、守规则可推断成功靠团队。"}, {"q": "In the passage, ''the air was thin'' means there was ____.", "answer": "A", "options": ["less oxygen high on the mountain", "a lot of dust in the air", "a cold strong wind", "thick white cloud"], "explanation": "高山空气稀薄=氧气少,由 could not walk fast 可推断。"}]'::jsonb, '[{"word": "rope", "cn": "绳索"}, {"word": "steep", "cn": "陡峭的"}, {"word": "tent", "cn": "帐篷"}, {"word": "thin", "cn": "(空气)稀薄的"}, {"word": "blew", "cn": "吹(blow的过去式)"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U4', 'The light in the old house', 'For years, the old house at the end of our village had stood empty. No one lived there, and its windows were always dark. So one autumn night, when a light appeared in an upstairs room, the whole village began to wonder.

''Someone must be inside,'' said old Mr Chen. ''A light can''t turn itself on.''

''But it can''t be a thief,'' said my mother. ''A thief would keep the house dark, not bright.''

''It may be a traveller,'' said my father. ''Or it might be some children playing a game.''

For three nights the light came and went. Some people were a little afraid; others were only curious. ''The person can''t be dangerous,'' I said to myself. ''Nothing was stolen, and no one was hurt.''

At last, a few of us walked up to the house. The door was open. Inside, by the warm light of a small lamp, sat an old man. He was thin and tired, and his clothes were worn. ''I used to live here as a boy,'' he said softly. ''I had nowhere else to go.''

The village was quiet for a moment. Then my mother spoke. ''You shouldn''t be alone on a cold night. You should come and stay with us.'' And so he did. Sometimes the answer to a mystery is much kinder than we fear. From that night on, the old man was never alone again. Warm meals were brought to his door, and the empty house slowly became a real home.', '推理与善意(情态动词二·推测)', 254, 2, '[{"q": "Why did old Mr Chen think someone was inside?", "answer": "B", "options": ["Because he saw the old man.", "Because a light can''t turn itself on.", "Because a thief was caught.", "Because children were playing."], "explanation": "''A light can''t turn itself on''→一定有人。"}, {"q": "Who was really in the old house?", "answer": "C", "options": ["A dangerous thief.", "A young traveller.", "An old man who used to live there.", "Some children playing a game."], "explanation": "''sat an old man ... I used to live here as a boy''。"}, {"q": "What is the main idea of the passage?", "answer": "D", "options": ["Old houses are dangerous places.", "Thieves often hide in empty houses.", "Children should not play at night.", "A village''s fear turned into kindness."], "explanation": "全文由猜疑转为对孤老的善意。"}, {"q": "We can infer that the villagers were ____ at the end.", "answer": "A", "options": ["kind and ready to help the old man", "angry with the old man", "still afraid of the light", "sorry they had come"], "explanation": "母亲请他同住可推断村民善良。"}, {"q": "When the writer says the person ''can''t be dangerous'', he means it is ____.", "answer": "A", "options": ["impossible that the person is dangerous", "certain that the person is a thief", "possible that something was stolen", "clear that someone was hurt"], "explanation": "can''t be=不可能是,表否定推测。"}]'::jsonb, '[{"word": "upstairs", "cn": "楼上的"}, {"word": "thief", "cn": "小偷"}, {"word": "traveller", "cn": "旅行者"}, {"word": "curious", "cn": "好奇的"}, {"word": "worn", "cn": "破旧的(wear的过去分词)"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U5', 'The secrets inside amber', 'Deep in a quiet forest, millions of years ago, a drop of sticky liquid fell from an old tree. A small insect was trapped inside it. Slowly, over a very long time, the liquid grew hard and turned into amber. Today, scientists have found that this golden stone can keep tiny living things safe for millions of years.

When researchers look through a magnifier, they see that the insect looks almost alive. Every leg and every hair is still there. Sometimes a feather or a leaf is found inside too. Scientists believe that these tiny pieces can unlock many secrets of the past. No museum and no photograph can show what a single piece of amber shows so well.

People once thought that we could never know the ancient world. But amber has changed this idea. Studying it, researchers now understand that some insects have hardly changed in millions of years, while others have disappeared for ever. In one famous piece of amber, scientists once found a tiny feather from a dinosaur. They were amazed, because it showed that some dinosaurs were covered with feathers, not scales. They have also learnt that the earth was once much warmer than it is today.

Every piece of amber tells a story. It reminds us that our planet is very old, and that life has taken countless forms. Scientists hope that one day, amber will help us understand not only the past, but also the future of life on the earth.', '科学发现(宾语从句·that)', 248, 2, '[{"q": "How did the amber form long ago?", "answer": "B", "options": ["An insect painted it gold.", "A drop of sticky liquid fell and slowly grew hard.", "Scientists made it in a factory.", "A tree turned into stone."], "explanation": "''a drop of sticky liquid fell ... turned into amber''。"}, {"q": "What do scientists believe the tiny pieces in amber can do?", "answer": "C", "options": ["Make the insect alive again.", "Turn into new trees.", "Unlock many secrets of the past.", "Change the earth''s weather."], "explanation": "''these tiny pieces can unlock many secrets of the past''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to make golden stones.", "Why insects disappear.", "How amber helps scientists learn about the ancient world.", "Where old forests grow."], "explanation": "全文讲琥珀帮助科学家了解远古。"}, {"q": "From the passage, we can infer that amber is valuable to scientists because it ____.", "answer": "A", "options": ["keeps ancient life safe for study", "is made of pure gold", "can bring insects back to life", "grows on old trees today"], "explanation": "由''保存远古生物、解锁过去''可推断其研究价值。"}, {"q": "In the passage, ''countless forms'' means forms that are ____.", "answer": "A", "options": ["too many to count", "very small and weak", "made of stone", "found only in amber"], "explanation": "countless=数不清的。"}]'::jsonb, '[{"word": "amber", "cn": "琥珀"}, {"word": "insect", "cn": "昆虫"}, {"word": "sticky", "cn": "黏的"}, {"word": "magnifier", "cn": "放大镜"}, {"word": "countless", "cn": "无数的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U6', 'The painter of the seasons', 'In a small mountain town lived an old painter named Grandpa Wen. For fifty years, he painted the same subject: the 24 Solar Terms, the ancient Chinese way of dividing the year into seasons. Many visitors wondered why he never grew tired of it.

''People often ask me when I will paint something new,'' Grandpa Wen once said with a smile. ''But they do not always understand what these old terms mean to me.''

Long ago, farmers used the 24 Solar Terms to decide when to plant and when to rest. Grandpa Wen still remembered how his grandfather watched the sky and the fields. Each term had its own feeling. In his paintings, a boy runs after the first spring wind; an old woman rests under a green tree in the summer heat; wild geese fly south as autumn comes; a warm lamp glows on a long winter night.

Younger people did not always know whether these old terms still mattered. Grandpa Wen wanted to show them that they did. He often explained why the seasons change and how people once lived close to nature. Slowly, his simple paintings became popular, and visitors came from faraway cities. No one could say for sure how the news spread. Some visitors even asked whether they could learn to paint like him, and he always welcomed them warmly.

Before he grew very old, Grandpa Wen gave all his paintings to the town school. ''I do not know whether these children will become painters,'' he said softly. ''But I hope they will remember where their culture comes from, and why it still lives today.''', '二十四节气与艺术(宾语从句·if/whether/wh)·改写(老树真人IP→虚构画家)', 268, 2, '[{"q": "What did Grandpa Wen paint for fifty years?", "answer": "B", "options": ["Faraway cities.", "The 24 Solar Terms.", "His own grandfather.", "The town school."], "explanation": "''For fifty years, he painted the same subject: the 24 Solar Terms''。"}, {"q": "In the past, what did farmers use the 24 Solar Terms to decide?", "answer": "C", "options": ["Whether to become painters.", "How to sell paintings.", "When to plant and when to rest.", "Where to build a school."], "explanation": "''farmers used the 24 Solar Terms to decide when to plant and when to rest''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to become a famous painter.", "Why young people leave their hometown.", "An old painter who kept a piece of Chinese culture alive through art.", "How the weather changes in the mountains."], "explanation": "全文借虚构画家讲用艺术传承节气文化。"}, {"q": "Why did Grandpa Wen give his paintings to the town school?", "answer": "A", "options": ["He hoped the children would remember their culture.", "He wanted the children to sell them.", "He needed more room at home.", "He was asked to by the government."], "explanation": "结尾''I hope they will remember where their culture comes from''。"}, {"q": "In the passage, ''these old terms still mattered'' means the terms were still ____.", "answer": "A", "options": ["important and worth keeping", "difficult to paint", "known only to farmers", "used to sell things"], "explanation": "matter=要紧、有意义,由传承主题可推断。"}]'::jsonb, '[{"word": "subject", "cn": "(绘画等的)题材"}, {"word": "terms", "cn": "节气(24 Solar Terms 二十四节气)"}, {"word": "geese", "cn": "大雁(goose的复数)"}, {"word": "glows", "cn": "发出柔光"}, {"word": "culture", "cn": "文化"}]'::jsonb);

-- 断言
DO $$
DECLARE rn int; qbad int; orphan int; poll int;
BEGIN
  SELECT count(*) INTO rn FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8B';
  SELECT count(*) INTO qbad FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8B' AND jsonb_array_length(questions)<>5;
  SELECT count(*) INTO orphan FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8B' AND unit IS NULL;
  SELECT count(*) INTO poll FROM public.junior_reading WHERE volume='wy8B' AND publisher<>'junior_fltrp';
  IF rn<>6 THEN RAISE EXCEPTION 'reading=% 期望6', rn; END IF;
  IF qbad<>0 THEN RAISE EXCEPTION '题数≠5的篇=%', qbad; END IF;
  IF orphan<>0 THEN RAISE EXCEPTION 'unit空=%', orphan; END IF;
  IF poll<>0 THEN RAISE EXCEPTION 'pep_polluted=%', poll; END IF;
  RAISE NOTICE 'OK: wy8B 阅读 % 篇', rn;
END $$;

COMMIT;
SELECT unit, title, word_count, jsonb_array_length(questions) qn FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8B' ORDER BY unit;